// Existing 16px toolbar symbols, drawn in the contrasting foreground color.
static void _viv_footer_icon(NMTBCUSTOMDRAW *d){RECT r=d->nmcd.rc;int x=(r.left+r.right)/2,y=(r.top+r.bottom)/2,id=(int)d->nmcd.dwItemSpec;COLORREF bg=_viv_exif_background(),fg=ui_text(bg);HGDIOBJ oldp,oldb;HPEN p;HBRUSH b;POINT points[3];if(d->nmcd.uItemState&(CDIS_HOT|CDIS_CHECKED|CDIS_SELECTED))ui_fill(d->nmcd.hdc,&r,ui_mix(bg,15));if(d->nmcd.uItemState&CDIS_DISABLED)fg=ui_muted(bg);p=CreatePen(PS_SOLID,1,fg);b=CreateSolidBrush(fg);oldp=SelectObject(d->nmcd.hdc,p);oldb=SelectObject(d->nmcd.hdc,b);if(id==VIV_ID_NAV_PREV || id==VIV_ID_NAV_NEXT || id==VIV_ID_SLIDESHOW_PLAY_ONLY){int dir=id==VIV_ID_NAV_PREV?-1:1;points[0].x=x+dir*4;points[0].y=y;points[1].x=x-dir*3;points[1].y=y-4;points[2].x=x-dir*3;points[2].y=y+4;Polygon(d->nmcd.hdc,points,3);if(id!=VIV_ID_SLIDESHOW_PLAY_ONLY){MoveToEx(d->nmcd.hdc,x-dir*6,y-4,NULL);LineTo(d->nmcd.hdc,x-dir*6,y+5);}}else if(id==VIV_ID_SLIDESHOW_PAUSE_ONLY){Rectangle(d->nmcd.hdc,x-4,y-4,x-1,y+5);Rectangle(d->nmcd.hdc,x+2,y-4,x+5,y+5);}else{SelectObject(d->nmcd.hdc,GetStockObject(NULL_BRUSH));Rectangle(d->nmcd.hdc,x-6,y-4,x+7,y+5);if(id==VIV_ID_VIEW_1TO1){MoveToEx(d->nmcd.hdc,x,y-2,NULL);LineTo(d->nmcd.hdc,x,y+3);}else{MoveToEx(d->nmcd.hdc,x-3,y,NULL);LineTo(d->nmcd.hdc,x+4,y);MoveToEx(d->nmcd.hdc,x,y-2,NULL);LineTo(d->nmcd.hdc,x,y+3);}}SelectObject(d->nmcd.hdc,oldp);SelectObject(d->nmcd.hdc,oldb);DeleteObject(p);DeleteObject(b);}
